impl api::v1::SearchQuery {
    /// Fail if this message does not satisfy `api/v1` field rules.
    pub fn require_valid(&self) -> Result<(), api::v1::Error> {
        require_valid(self)
    }
}

impl api::v1::HistoryEntry {
    /// UTC commit instant. Git `Time.seconds` is already seconds since epoch.
    #[must_use]
    pub fn with_time(mut self, unix_seconds: i64) -> Self {
        self.time = buffa_types::google::protobuf::Timestamp::from_unix_secs(unix_seconds).into();
        self
    }
}

#[cfg(test)]
mod tests {
    use protovalidate_buffa::Validate;

    use super::api::v1::{Error, Filter, HistoryEntry, OpenOptions, Record, SearchHit, SearchQuery};

    #[test]
    fn error_json_uses_lib5_code_string() {
        let err = Error::default()
            .with_code("not_found")
            .with_message("missing id");
        let json = serde_json::to_value(&err).expect("json");
        assert_eq!(json["code"], "not_found");
        assert_eq!(json["message"], "missing id");
    }

    #[test]
    fn open_options_json_uses_protobuf_json_names() {
        let opts = OpenOptions::default()
            .with_write(true)
            .with_auto_sync(false);
        let json = serde_json::to_value(&opts).expect("json");
        assert_eq!(json["write"], true);
        assert_eq!(json["autoSync"], false);
        assert!(json.get("indexDir").is_none());
        assert!(json.get("remoteRepo").is_none());
        let cloned = OpenOptions::new().remote_repo("file:///tmp/scheda.git");
        let json = serde_json::to_value(&cloned).expect("json");
        assert_eq!(json["remoteRepo"], "file:///tmp/scheda.git");
    }

    #[test]
    fn record_fields_are_a_json_object() {
        let record = Record::default()
            .with_id("alpha")
            .with_collection("notes")
            .with_valid(true);
        let json = serde_json::to_value(&record).expect("json");
        assert_eq!(json["id"], "alpha");
        assert_eq!(json["collection"], "notes");
        assert_eq!(json["valid"], true);
    }

    #[test]
    fn error_code_is_required() {
        assert!(Error::default().validate().is_err());
        assert!(Error::default().with_code("not_found").validate().is_ok());
    }

    #[test]
    fn open_options_default_is_valid() {
        assert!(OpenOptions::default().validate().is_ok());
        assert!(OpenOptions::new().require_valid().is_ok());
    }

    #[test]
    fn empty_filter_is_valid() {
        assert!(Filter::default().validate().is_ok());
        assert!(Filter::default().require_valid().is_ok());
    }

    #[test]
    fn record_id_and_collection_are_required() {
        assert!(Record::default().validate().is_err());
        assert!(
            Record::default()
                .with_id("alpha")
                .with_collection("notes")
                .validate()
                .is_ok()
        );
        let err = Record::default()
            .require_valid()
            .expect_err("missing id and collection");
        assert_eq!(err.code.as_deref(), Some("invalid"));
        assert!(
            Record::default()
                .with_id("alpha")
                .with_collection("a/b")
                .require_valid()
                .is_ok()
        );
        let err = Record::default()
            .with_id("a/b")
            .with_collection("notes")
            .require_valid()
            .expect_err("id slash");
        assert_eq!(err.code.as_deref(), Some("invalid"));
        let err = Record::default()
            .with_id("a\\b")
            .with_collection("notes")
            .require_valid()
            .expect_err("id backslash");
        assert_eq!(err.code.as_deref(), Some("invalid"));
    }

    #[test]
    fn history_entry_time_is_required() {
        assert!(HistoryEntry::default().with_hash("abc").validate().is_err());
        assert!(
            HistoryEntry::default()
                .with_hash("abc")
                .with_time(0)
                .validate()
                .is_ok()
        );
    }

    #[test]
    fn history_entry_time_json_is_rfc3339() {
        let json = serde_json::to_value(HistoryEntry::default().with_time(0)).expect("json");
        assert_eq!(json["time"], "1970-01-01T00:00:00Z");
    }

    #[test]
    fn search_query_text_is_required() {
        assert!(SearchQuery::default().validate().is_err());
        assert!(
            SearchQuery::default()
                .with_text("token")
                .require_valid()
                .is_ok()
        );
        let err = SearchQuery::default()
            .require_valid()
            .expect_err("missing text");
        assert_eq!(err.code.as_deref(), Some("invalid"));
    }

    #[test]
    fn search_query_weights_are_finite_and_non_negative() {
        let ok = SearchQuery::default().with_text("token");
        assert!(ok.require_valid().is_ok());
        assert!(
            ok.clone()
                .with_lexical_weight(0.0)
                .with_vector_weight(0.0)
                .require_valid()
                .is_ok()
        );
        let err = ok
            .clone()
            .with_lexical_weight(-1.0)
            .require_valid()
            .expect_err("negative lexical_weight");
        assert_eq!(err.code.as_deref(), Some("invalid"));
        let err = ok
            .clone()
            .with_vector_weight(f64::NAN)
            .require_valid()
            .expect_err("NaN vector_weight");
        assert_eq!(err.code.as_deref(), Some("invalid"));
        let err = ok
            .clone()
            .with_lexical_weight(f64::INFINITY)
            .require_valid()
            .expect_err("+Inf lexical_weight");
        assert_eq!(err.code.as_deref(), Some("invalid"));
        let err = ok
            .with_vector_weight(f64::NEG_INFINITY)
            .require_valid()
            .expect_err("-Inf vector_weight");
        assert_eq!(err.code.as_deref(), Some("invalid"));
    }

    #[test]
    fn search_hit_scores_are_finite_and_non_negative() {
        let ok = SearchHit::default()
            .with_collection("notes")
            .with_id("alpha");
        assert!(ok.validate().is_ok());
        assert!(ok.clone().with_rrf_score(0.0).validate().is_ok());
        assert!(ok.clone().with_rrf_score(-0.1).validate().is_err());
        assert!(ok.clone().with_lexical_score(f64::NAN).validate().is_err());
        assert!(ok.clone().with_rrf_score(f64::INFINITY).validate().is_err());
        assert!(ok.with_vector_score(f64::NEG_INFINITY).validate().is_err());
    }
}
